function setCategoryOptions(id,items){document.getElementById(id).innerHTML=items.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}
function applyCategorySetup(cat){const s=CATEGORY_SETUP_SCHEMAS[cat],ids=['productNameInput','salesTargetSelect','productTypeSelect','priceInput','productDescriptionInput','productBenefitsInput',null,'dealSceneSelect','customerAttitudeSelect','roleplayDifficultySelect','roleplayGoalSelect'];document.querySelector('#screen-setup .page-header h2').textContent=s.title;ids.forEach((id,i)=>{const l=id?document.querySelector(`label[for="${id}"]`):document.querySelector('#customerAvatarGrid').closest('.field').querySelector('label');if(l)l.innerHTML=`${i+1} ${s.labels[i]} <span class="optional-tag">変更可</span>`});setCategoryOptions('salesTargetSelect',s.target);setCategoryOptions('productTypeSelect',s.type);setCategoryOptions('dealSceneSelect',s.scene);setCategoryOptions('roleplayGoalSelect',s.goal);const contextField=document.getElementById('priceInput');if(contextField){contextField.readOnly=false;contextField.classList.remove('fixed-field');contextField.placeholder={sales:'例：月額3万円 / 見積制',manager:'例：3年',interview:'例：年収500〜700万円',support:'例：契約額10万円'}[cat]||''}const sales=cat==='sales';document.getElementById('btobDetails').hidden=!sales;document.getElementById('btocDetails').hidden=true;document.getElementById('commonSalesDetails').hidden=!sales;const b=document.getElementById('categoryDetails');b.hidden=sales;if(!sales)b.innerHTML=s.details.map((x,i)=>`<div class="field"><label>${x}</label><input id="categoryDetail${i}" placeholder="選択または自由入力" oninput="updateSetupDraft()"></div>`).join('')}
function categoryDraftKey(){return ROLEPLAY_DRAFT_KEY+'_'+state.category}
function collectCategoryConfig(){const c=collectRoleplayConfig();c.category=state.category;c.advanced={...c.advanced,...Object.fromEntries([...document.querySelectorAll('#categoryDetails input')].map((e,i)=>[CATEGORY_SETUP_SCHEMAS[state.category].details[i],e.value.trim()]))};return c}
const populateBase=populateRoleplayConfig;
populateRoleplayConfig=function(c){populateBase(c);[...document.querySelectorAll('#categoryDetails input')].forEach((e,i)=>e.value=c.advanced?.[CATEGORY_SETUP_SCHEMAS[state.category].details[i]]||'')}
startSetup=function(cat='sales'){state.category=CATEGORY_SETUP_SCHEMAS[cat]?cat:'sales';state.scenarioId=SCENARIOS[state.category][0].id;state.mode='practice';state.interaction='voice';state.roleplayConfig=defaultRoleplayConfig();state.roleplayConfig.category=state.category;state.advancedOpen=false;applyCategorySetup(state.category);try{state.roleplayConfig={...state.roleplayConfig,...JSON.parse(localStorage.getItem(categoryDraftKey())||'{}')}}catch{}if(state.category==='manager'&&/^(?:5分（固定）|\d+\s*分)$/.test(state.roleplayConfig.product?.price||''))state.roleplayConfig.product.price='3年';state.avatarId=customerAppearance().assetId;populateRoleplayConfig(state.roleplayConfig);renderSetup();showScreen('setup')}
updateSetupDraft=function(targetChanged=false){if(!document.getElementById('productNameInput'))return;state.roleplayConfig=collectCategoryConfig();try{localStorage.setItem(categoryDraftKey(),JSON.stringify(state.roleplayConfig))}catch{}if(targetChanged&&state.category==='sales')renderAdvancedTarget();updateSummary()}
renderSetup=function(){renderCustomerAvatars();if(state.category==='sales')renderAdvancedTarget();document.getElementById('advancedSettings').hidden=!state.advancedOpen;updateSummary()}
updateSummary=function(){if(!document.getElementById('summaryProduct'))return;const c=collectCategoryConfig(),a=customerAppearance(),s=CATEGORY_SETUP_SCHEMAS[state.category];document.getElementById('summaryAvatar').src=avatarImage(a.assetId,'positive',true);document.getElementById('summaryName').textContent=a.label;document.getElementById('summaryRole').textContent=CATEGORY_LABELS[state.category];document.querySelector('#summaryProduct').previousElementSibling.textContent=s.labels[0];document.getElementById('summaryProduct').textContent=c.product.name||'未入力';document.querySelector('#summaryScene').previousElementSibling.textContent=s.labels[7];document.getElementById('summaryScene').textContent=c.deal.scene;document.getElementById('summaryAttitude').textContent=c.deal.attitude;document.getElementById('summaryDifficulty').textContent={easy:'初級',normal:'中級',hard:'上級'}[c.deal.difficulty];document.getElementById('summaryGoal').textContent=c.deal.goal}
function scenarioIdForCategory(c){if(state.category==='manager')return c.deal.scene==='退職相談'?'manager_retention':c.deal.scene==='改善指導'?'manager_guidance':c.deal.scene==='評価フィードバック'?'manager_feedback':'manager_1on1';if(state.category==='interview')return c.product.target==='新卒採用'?'interview_newgrad':c.product.target==='管理職採用'?'interview_manager':'interview_midcareer';if(state.category==='support')return c.product.type==='料金・契約'?'support_refund':c.deal.scene==='エスカレーション'?'support_custharass':'support_delay';return sceneScenario(c.deal.scene)}





