applyCategorySetup=function(category){applyCategorySetupExamplesBase(category);const e=CATEGORY_EXAMPLES[category],basicIds=['productNameInput','priceInput','productDescriptionInput','productBenefitsInput'];basicIds.forEach((id,i)=>{const el=document.getElementById(id);if(el)el.placeholder=e.basic[i]});if(category==='sales')DETAIL_IDS.forEach((id,i)=>{const el=document.getElementById(id);if(el)el.placeholder=e.details[i]||'選択または自由入力'});else [...document.querySelectorAll('#categoryDetails input')].forEach((el,i)=>el.placeholder=e.details[i]||'選択または自由入力')};
categoryDraftKey=function(){return ROLEPLAY_DRAFT_KEY+'_'+state.category+'_v3'};

function showInformation(id='pricing'){showScreen('information');document.querySelectorAll('.info-section').forEach(el=>el.hidden=el.id!==('info-'+id));document.querySelectorAll('.info-link').forEach(el=>el.classList.toggle('active',el.dataset.info===id));const selected=[...document.querySelectorAll('.info-link')].find(el=>el.dataset.info===id);document.getElementById('informationTitle').textContent=selected?.textContent||'サービス情報';}


// Public briefing and hidden scenario design.
function scenarioDesignCopy(){return globalThis.ScenarioDesign?.categoryCopy?.(state.category)||{publicLabel:'事前に分かっていること',publicHelp:'開始前から確認できている事実だけを入力します。',publicPlaceholder:'事前情報を入力',directionLabel:'本音の方向性',directionPlaceholder:'方向性を入力',truthLabel:'相手の本音・背景',truthPlaceholder:'本音を入力',conditionsLabel:'判断条件・譲れないこと',conditionsPlaceholder:'条件を入力'}}
function currentScenarioMode(){const mode=state.roleplayConfig?.customer?.scenarioMode;return ['auto','guided','manual'].includes(mode)?mode:'auto'}
function renderScenarioDesign(){const copy=scenarioDesignCopy(),mode=currentScenarioMode();document.querySelectorAll('[data-scenario-mode]').forEach(button=>{const selected=button.dataset.scenarioMode===mode;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});const guided=document.getElementById('scenarioGuidedFields'),manual=document.getElementById('scenarioManualFields'),auto=document.getElementById('scenarioAutoNote');if(guided)guided.hidden=mode!=='guided';if(manual)manual.hidden=mode!=='manual';if(auto)auto.hidden=mode!=='auto';const labels={hiddenDirectionLabel:copy.directionLabel,hiddenTruthLabel:copy.truthLabel+' ',hiddenConditionsLabel:copy.conditionsLabel};Object.entries(labels).forEach(([id,value])=>{const el=document.getElementById(id);if(el){el.textContent=value;if(id==='hiddenTruthLabel')el.insertAdjacentHTML('beforeend','<em>必須</em>')}});const placeholders={hiddenDirectionInput:copy.directionPlaceholder,hiddenTruthInput:copy.truthPlaceholder,hiddenConditionsInput:copy.conditionsPlaceholder};Object.entries(placeholders).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.placeholder=value})}
function setScenarioDesignMode(mode){if(!['auto','guided','manual'].includes(mode))return;const config=collectCategoryConfig();config.customer.scenarioMode=mode;config.customer.hiddenProfile=null;state.roleplayConfig=config;try{localStorage.setItem(categoryDraftKey(),JSON.stringify(config))}catch{}renderScenarioDesign();updateSummary()}
function currentDiscoveryProfile(){return state.roleplayConfig?.customer?.hiddenProfile||null}
function currentDiscoveryReview(){const profile=currentDiscoveryProfile()||{};return globalThis.ScenarioDesign?.analyzeDiscovery?.({category:state.category,conversation:state.conversation,profile})||{score:0,discovered:'ヒアリング内容を確認できませんでした。',missed:'相手の状況を具体的に確認しましょう。',hiddenSummary:profile.hiddenTruth||scenario().hiddenNeed}}
function roleLabelForCategory(config){const labels={sales:config.product.target==='BtoB'||config.product.target==='btob'?'法人顧客':'個人顧客',manager:config.product.type||'面談を受ける部下',interview:config.product.target||'応募者',support:config.product.target||'顧客'};return `${labels[state.category]||CATEGORY_LABELS[state.category]}｜${config.deal.scene}`}
function openingForCategory(){return scenario().opening||'本日はよろしくお願いします。'}
const applyCategorySetupDiscoveryBase=applyCategorySetup;
applyCategorySetup=function(category){applyCategorySetupDiscoveryBase(category);const copy=scenarioDesignCopy(),label=document.querySelector('label[for="customerNeedsInput"]'),help=document.getElementById('publicFactsHelp'),input=document.getElementById('customerNeedsInput');if(label)label.innerHTML=`⑧ ${escapeHtml(copy.publicLabel)} <span class="optional-tag">任意</span>`;if(help)help.textContent=copy.publicHelp;if(input)input.placeholder=copy.publicPlaceholder;renderScenarioDesign()};
const renderSetupDiscoveryBase=renderSetup;
renderSetup=function(){renderSetupDiscoveryBase();renderScenarioDesign()};
const updateSummaryDiscoveryBase=updateSummary;
updateSummary=function(){updateSummaryDiscoveryBase();const summary=document.getElementById('summaryScenarioMode');if(summary)summary.textContent=globalThis.ScenarioDesign?.MODES?.[currentScenarioMode()]||'AIにおまかせ'};
const beginRoleplayDiscoveryBase=beginRoleplay;
beginRoleplay=async function(){const config=collectCategoryConfig(),mode=config.customer.scenarioMode||'auto',validation=document.getElementById('setupValidation');if(mode==='guided'&&!config.customer.hiddenDirection){validation.hidden=false;validation.textContent='「方向性だけ指定」では、本音の方向性を入力してください。';document.getElementById('hiddenDirectionInput')?.focus();return}if(mode==='manual'&&!config.customer.hiddenTruth){validation.hidden=false;validation.textContent='「すべて自分で設定」では、相手の本音・背景を入力してください。';document.getElementById('hiddenTruthInput')?.focus();return}state.scenarioId=scenarioIdForCategory(config);const profile=globalThis.ScenarioDesign?.buildHiddenProfile?.({category:state.category,config,scenario:scenario(),difficulty:config.deal.difficulty});if(profile)config.customer.hiddenProfile=profile;state.roleplayConfig=config;return beginRoleplayDiscoveryBase()};
const localReplyDiscoveryBase=localReply;
localReply=function(text,analysis){const profile=currentDiscoveryProfile(),turnThreshold={easy:1,normal:2,hard:3}[state.difficulty]||2,trustThreshold={easy:40,normal:48,hard:58}[state.difficulty]||48;if(profile&&analysis.openQuestion&&state.turn>=turnThreshold&&state.trust>=trustThreshold){if(/(条件|決裁|予算|時期|支援|希望|解決|入社|懸念|譲れ)/.test(text)&&profile.hiddenConditions)return String(profile.hiddenConditions).slice(0,180);return String(profile.hiddenTruth||'').slice(0,180)||localReplyDiscoveryBase(text,analysis)}return localReplyDiscoveryBase(text,analysis)};
function enrichDiscoveryResult(result,data={}){if(!result)return result;const review=currentDiscoveryReview(),profile=currentDiscoveryProfile()||{};result.discoveryScore=Number.isFinite(Number(data.discoveryScore))?clamp(Number(data.discoveryScore)):review.score;result.discovered=sanitizeAvatarReferences(data.discovered)||review.discovered;result.missed=sanitizeAvatarReferences(data.missed)||review.missed;result.hiddenNeed=sanitizeAvatarReferences(data.hiddenNeed)||review.hiddenSummary||profile.hiddenTruth||scenario().hiddenNeed;result.discoveryProfile=profile;return result}
const normalizeEvaluationDiscoveryBase=normalizeEvaluation;
normalizeEvaluation=function(data){return enrichDiscoveryResult(normalizeEvaluationDiscoveryBase(data),data||{})};
const buildLocalEvaluationDiscoveryBase=buildLocalEvaluation;
buildLocalEvaluation=function(){return enrichDiscoveryResult(buildLocalEvaluationDiscoveryBase())};
const renderResultsDiscoveryBase=renderResults;
renderResults=function(result){renderResultsDiscoveryBase(result);const score=clamp(Number(result.discoveryScore||0)),scoreEl=document.getElementById('discoveryScore'),bar=document.getElementById('discoveryProgress'),discovered=document.getElementById('discoveredFeedback'),missed=document.getElementById('missedFeedback');if(scoreEl)scoreEl.textContent=Math.round(score);if(bar)bar.style.width=`${score}%`;if(discovered)discovered.textContent=result.discovered||'—';if(missed)missed.textContent=result.missed||'—'};

// AI execution modes: Cloudflare Workers AI or one of three on-device models via WebLLM.
let localModelState='idle';
let localModelProgress=0;
let localModelMessage='未準備です。モデル本体はブラウザ内へ保存されます。';
function isLocalMode(){return settings.aiMode==='local'}
function localAIPayload(action,userText=''){return {action,category:state.category,scenario:scenario(),avatar:roleplayAvatarPayload(),persona:persona(),difficulty:difficulty(),topic:state.topic,context:state.context,promptSettings:{meetingStage:state.meetingStage,knownIssue:state.knownIssue,conversationGoal:state.conversationGoal,constraints:state.constraints},metrics:{trust:state.trust,interest:state.interest,stress:state.stress},phase:scenario().phases[state.phaseIndex],conversation:action==='reply'?state.conversation.slice(-12):state.conversation,userText,roleplayConfig:state.roleplayConfig,audioStats:state.audioStats,companyProfile:String(settings.companyProfile||'').slice(0,12000)}}
async function ensureLocalAIReady(){if(!globalThis.LocalAI)throw new Error('端末内AIモジュールを読み込めませんでした。');if(localModelState==='ready')return true;return prepareLocalModel(true)}
async function fetchLocalAIReply(userText){try{await ensureLocalAIReady();return await globalThis.LocalAI.reply(localAIPayload('reply',userText))}catch(error){console.error('Local model reply failed',error);const analysis=analyzeUserMessage(userText);toast('端末内AIの応答が遅いため、高速応答へ切り替えました');return {reply:localReply(userText,analysis),emotion:deriveEmotion(),deltas:{trust:analysis.openQuestion?2:0,interest:analysis.value?2:0,stress:analysis.pushy?4:0}}}}
async function fetchLocalAIEvaluation(){try{await ensureLocalAIReady();return normalizeEvaluation(await globalThis.LocalAI.evaluate(localAIPayload('evaluate')))}catch(error){console.error('Local model evaluation failed',error);toast('端末内AIで採点できないため、端末内の基本採点を表示します');return null}}
function setAIMode(mode){if(!['cloud','local'].includes(mode))return;settings.aiMode=mode;if(mode==='local'){stopVoiceRuntime(true);state.interaction='text'}saveSettings();probeAPI();toast(mode==='local'?'社内情報モードへ切り替えました':'通常モードへ切り替えました')}
function changeLocalModel(value){if(!LOCAL_MODEL_IDS.has(value))return;settings.localModel=value;localModelState='idle';localModelProgress=0;localModelMessage='選択したモデルは未準備です。';saveSettings()}
function changeCompanyProfile(value){settings.companyProfile=String(value||'').slice(0,12000);try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}catch{}}
async function prepareLocalModel(fromStart=false){const api=globalThis.LocalAI;if(!api){localModelState='error';localModelMessage='端末内AIモジュールを読み込めませんでした。';renderSettings();if(fromStart)throw new Error(localModelMessage);return false}const support=api.support();if(!support.webgpu){localModelState='error';localModelMessage='WebGPU非対応です。最新版のChromeまたはEdgeでお試しください。';renderSettings();if(fromStart)throw new Error(localModelMessage);return false}localModelState='loading';localModelProgress=0;localModelMessage='選択したモデルをダウンロードしています。画面を閉じないでください。';renderSettings();try{await api.prepare({modelId:settings.localModel,onProgress:({progress,text})=>{localModelProgress=Math.round(progress*100);localModelMessage=text||`モデルを準備中 ${localModelProgress}%`;renderLocalModelProgress()}});localModelState='ready';localModelProgress=100;localModelMessage='準備完了。会話と採点はこの端末内で処理されます。';renderSettings();toast('端末内モデルの準備が完了しました');return true}catch(error){localModelState='error';localModelMessage=error?.message||String(error||'モデルを準備できませんでした。');renderSettings();if(fromStart)throw error;toast(localModelMessage);return false}}
async function deleteLocalModel(){if(!confirm('選択中のローカルモデルをこの端末から削除しますか？'))return;try{await globalThis.LocalAI?.remove(settings.localModel);localModelState='idle';localModelProgress=0;localModelMessage='モデルを削除しました。';renderSettings();toast('端末内モデルを削除しました')}catch(error){toast(error.message||'モデルを削除できませんでした')}}
function renderLocalModelProgress(){const fill=document.getElementById('localModelProgressFill'),status=document.getElementById('localModelStatus'),detail=document.getElementById('localModelStatusDetail'),button=document.getElementById('localModelPrepareButton'),setupDescription=document.getElementById('setupAIModeDescription');if(fill)fill.style.width=`${localModelProgress}%`;if(status)status.textContent={idle:'未準備',loading:`準備中 ${localModelProgress}%`,cached:'保存済み',ready:'準備完了',error:'エラー'}[localModelState]||'未準備';if(detail)detail.textContent=localModelMessage;if(button){button.disabled=localModelState==='loading';button.textContent=localModelState==='ready'?'準備済み':localModelState==='loading'?'準備中…':'モデルを準備'}if(setupDescription&&isLocalMode()&&localModelState==='loading')setupDescription.textContent=`ローカルモデルを端末へ準備中 ${localModelProgress}%`}
async function inspectLocalModelCache(){if(!globalThis.LocalAI||localModelState==='ready'||localModelState==='loading')return;try{if(await globalThis.LocalAI.cached(settings.localModel)){localModelState='cached';localModelProgress=100;localModelMessage='モデルはこの端末に保存済みです。開始時に読み込みます。';renderLocalModelProgress()}}catch{}}
function renderAIModeSettings(){const local=isLocalMode(),support=globalThis.LocalAI?.support?.()||{webgpu:false,deviceMemoryGB:0};document.body.classList.toggle('local-ai-mode',local);document.getElementById('cloudModeCard')?.classList.toggle('selected',!local);document.getElementById('localModeCard')?.classList.toggle('selected',local);const localPanel=document.getElementById('localAISettings');if(localPanel)localPanel.hidden=!local;const endpoint=document.getElementById('cloudAIEndpointRow');if(endpoint)endpoint.hidden=local;const model=document.getElementById('localModelSelect');if(model)model.value=settings.localModel;const profile=document.getElementById('companyProfileInput');if(profile&&profile.value!==settings.companyProfile)profile.value=settings.companyProfile||'';const historySwitch=document.getElementById('localHistorySwitch');historySwitch?.classList.toggle('on',Boolean(settings.localSaveHistory));const badge=document.getElementById('localSupportBadge'),supportText=document.getElementById('localSupportText');if(badge)badge.textContent=support.webgpu?'対応':'非対応';if(supportText)supportText.textContent=support.webgpu?`WebGPU対応${support.deviceMemoryGB?`・メモリ目安 ${support.deviceMemoryGB}GB`:''}`:'最新版Chrome / EdgeとWebGPU対応GPUが必要です';const title=document.getElementById('setupAIModeTitle'),description=document.getElementById('setupAIModeDescription');if(title)title.textContent=local?'🔒 社内情報モード':'☁️ 通常モード';if(description)description.textContent=local?'会話・採点を選択した端末内AIで処理します。':'Cloudflare Workers AIで会話します。';document.getElementById('micButton')?.classList.toggle('hidden',local);renderLocalModelProgress();if(local)inspectLocalModelCache()}
renderSettings=function(){document.getElementById('speechSwitch')?.classList.toggle('on',settings.speech);document.getElementById('handsFreeSwitch')?.classList.toggle('on',settings.handsFree);document.getElementById('autoSendSwitch')?.classList.toggle('on',settings.autoSend);document.getElementById('premiumSwitch')?.classList.toggle('on',settings.premiumPreview);const endpointInput=document.getElementById('apiEndpointInput');if(endpointInput)endpointInput.value=settings.apiEndpoint||'';const rate=document.getElementById('speechRateRange');if(rate)rate.value=settings.speechRate;const rateValue=document.getElementById('speechRateValue');if(rateValue)rateValue.textContent=Number(settings.speechRate).toFixed(2);refreshVoiceSelects();const voice=document.getElementById('settingsVoiceSelect');if(voice)voice.value=settings.voiceURI;renderAIModeSettings();renderApiStatus();applyPlanPreview()};
resolvedTtsEngine=function(){return'browser'};
refreshKokoroVoiceSelects=function(){};
updateVoiceFieldVisibility=function(){};
renderKokoroStatus=function(){};
renderApiStatus=function(){const el=document.getElementById('apiStatus'),text=document.getElementById('apiStatusText');if(isLocalMode()){el?.classList.add('online');if(text)text.textContent=localModelState==='ready'?'端末内AI':'社内情報モード';return}el?.classList.toggle('online',apiAvailable);if(text)text.textContent=apiAvailable?'AI接続中':'基本会話モード'};
probeAPI=async function(){if(isLocalMode()){apiAvailable=false;renderApiStatus();return}const endpoint=getApiEndpoint();if(!settings.preferAI||(!settings.apiEndpoint&&location.protocol==='file:')){apiAvailable=false;renderApiStatus();return}try{const res=await fetch(endpoint,{method:'GET',cache:'no-store'}),data=await res.json();apiAvailable=res.ok&&data.aiConfigured!==false}catch{apiAvailable=false}renderApiStatus()};
const beginRoleplayModeBase=beginRoleplay;
beginRoleplay=async function(){if(isLocalMode()){const required=['productNameInput','priceInput','productDescriptionInput','productBenefitsInput'];if(required.every(id=>inputValue(id))){try{await ensureLocalAIReady()}catch(error){toast(error.message||'端末内AIを準備できませんでした');return}}state.interaction='text'}else state.interaction='voice';return beginRoleplayModeBase()};
const renderSetupModeBase=renderSetup;
renderSetup=function(){renderSetupModeBase();renderAIModeSettings()};
init=function(){setupSpeechRecognition();loadVoices();if('speechSynthesis'in window)window.speechSynthesis.onvoiceschanged=loadVoices;renderHome();renderSettings();probeAPI();initBilling();AVATARS.slice(0,3).forEach(a=>preloadAvatar(a.id));if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('service-worker.js',{updateViaCache:'none'}).catch(()=>{})};
init();
